    "distinguished": "t-dist", "doubted": "t-dist", "overruled": "t-dist",
    "referred": "t-ref", "referred to": "t-ref", "noted": "t-ref", "considered": "t-ref",
    "relied on": "t-rel", "relied-on": "t-rel", "relied upon": "t-rel",
